package com.commercecore.payment;import org.springframework.boot.context.properties.ConfigurationProperties;import java.time.Duration;@ConfigurationProperties("app.payment")public record PaymentReliabilityProperties(Duration timeout,int maxRetries,Duration retryDelay,int circuitFailureThreshold,Duration circuitOpenDuration){public PaymentReliabilityProperties{if(timeout==null)timeout=Duration.ofSeconds(5);if(maxRetries<0)maxRetries=1;if(retryDelay==null)retryDelay=Duration.ofMillis(100);if(circuitFailureThreshold<1)circuitFailureThreshold=5;if(circuitOpenDuration==null)circuitOpenDuration=Duration.ofSeconds(30);}}
